import type { HTMLAttributes, MouseEvent } from "react";
import { cx } from "../utils/cx";
import type { Tone } from "./badge";
import { CloseIcon } from "../icons/interface";

export type TagProps = HTMLAttributes<HTMLSpanElement> & {
  tone?: Extract<Tone, "neutral" | "accent" | "success" | "warning" | "danger">;
  /** Adds a remove button. */
  onRemove?: (event: MouseEvent<HTMLButtonElement>) => void;
  /** Accessible name of the remove button. Default "Remove". */
  removeLabel?: string;
};

/** A removable label or filter chip. Unlike `Badge` it can be dismissed. */
export function Tag({ tone = "neutral", onRemove, removeLabel = "Remove", className, children, ...rest }: TagProps) {
  return (
    <span {...rest} className={cx("hm-tag", className)} data-tone={tone}>
      {children}
      {onRemove ? (
        <button
          type="button"
          className="hm-tag-remove"
          aria-label={`${removeLabel} ${typeof children === "string" ? children : ""}`.trim()}
          onClick={onRemove}
        >
          <CloseIcon size={10} strokeWidth={1.8} />
        </button>
      ) : null}
    </span>
  );
}
